/**
 * The runtime vocabulary content validates and generates against.
 *
 * `runtime-contract.json` is generated by the engine (`cyberia stat-contract`) from the runtime
 * source of truth. This module reads it and derives the stat rules from it.
 *
 * @module src/schema/contract.js
 */
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const CONTRACT_FILE = fileURLToPath(new URL('./runtime-contract.json', import.meta.url));

/** @type {{itemTypes:string[], entityItemTypes:Object<string,string[]>, entityBehaviors:string[], lootBehaviors:string[],
 *   stats:{types:string[],default:number,min:number,max:number,bounds:Object<string,Object<string,[number,number]>>},
 *   skillLogic:Array<{id:string,summons:string|null}>, questStepTypes:string[], casterSkinPlaceholder:string,
 *   itemDialoguePrefix:string}} */
export const CONTRACT = Object.freeze(JSON.parse(readFileSync(CONTRACT_FILE, 'utf8')));

export const ENTITY_TYPES = Object.freeze(Object.keys(CONTRACT.entityItemTypes));

/** The dialogue code of an item: its flavor text, and an NPC's greeting when the item is its skin. */
export const itemDialogueCode = (itemId) => `${CONTRACT.itemDialoguePrefix}${itemId}`;

/**
 * Every stat of the contract, each one an integer inside the contract range.
 * @param {Object} [stats]
 * @returns {Object<string,number>} Stats in contract order, with the default for an absent stat.
 * @throws {TypeError|RangeError} When a stat is unknown or out of range.
 */
export function validateStats(stats = {}) {
  const { types, min, max } = CONTRACT.stats;
  if (!stats || typeof stats !== 'object' || Array.isArray(stats)) throw new TypeError('Stats must be an object.');
  for (const key of Object.keys(stats)) if (!types.includes(key)) throw new TypeError(`Unknown stat: ${key}`);
  return Object.fromEntries(
    types.map((key) => {
      const value = stats[key] ?? CONTRACT.stats.default;
      if (!Number.isInteger(value) || value < min || value > max)
        throw new RangeError(`Stat modifiers must be integers from ${min} to +${max}.`);
      return [key, value];
    }),
  );
}

/**
 * Stats inside the bounds of an item type: any number is rounded, and a stat that is not a number
 * takes the default.
 * @param {Object} [stats]
 * @param {string} itemType
 * @returns {Object<string,number>}
 */
export function clampStats(stats, itemType) {
  const bounds = CONTRACT.stats.bounds[itemType];
  return Object.fromEntries(
    CONTRACT.stats.types.map((key) => {
      const value = Math.round(Number(stats?.[key]));
      const [low, high] = bounds[key];
      return [key, Math.min(high, Math.max(low, Number.isFinite(value) ? value : CONTRACT.stats.default))];
    }),
  );
}
